int findTheWinner(int n, int k) {
    ListNode* head = new ListNode(1);    // friends 1..n sitting in a ring
    ListNode* tail = head;
    for (int i = 2; i <= n; i++) {
        tail->next = new ListNode(i);
        tail = tail->next;
    }
    tail->next = head;
    ListNode* prev = tail;               // the node before whoever counts "1"
    while (prev->next != prev) {         // until one friend is left
        for (int i = 0; i < k - 1; i++) prev = prev->next;   // count k - 1 friends
        ListNode* gone = prev->next;
        prev->next = gone->next;         // the k-th friend leaves the circle
        delete gone;
    }
    int winner = prev->val;
    delete prev;
    return winner;
}

function findTheWinner(n, k) {
  const friends = Array.from({ length: n }, (_, i) => i + 1);
  let start = 0;
  while (friends.length > 1) {
    const out = (start + k - 1) % friends.length;   // jump straight to the k-th friend
    friends.splice(out, 1);                          // the next friend slides into out
    start = out % friends.length;
  }
  return friends[0];
}

int findTheWinner(int n, int k) {
    List<Integer> friends = new ArrayList<>();
    for (int i = 1; i <= n; i++) friends.add(i);
    int start = 0;
    while (friends.size() > 1) {
        int out = (start + k - 1) % friends.size();   // jump straight to the k-th friend
        friends.remove(out);                           // the next friend slides into out
        start = out % friends.size();
    }
    return friends.get(0);
}

int findTheWinner(int n, int k) {
    vector<int> friends;
    for (int i = 1; i <= n; i++) friends.push_back(i);
    int start = 0;
    while (friends.size() > 1) {
        int out = (start + k - 1) % friends.size();   // jump straight to the k-th friend
        friends.erase(friends.begin() + out);          // the next friend slides into out
        start = out % friends.size();
    }
    return friends[0];
}

function findTheWinner(n, k) {
  let winner = 0;                        // with 1 friend, the winner is seat 0
  for (let size = 2; size <= n; size++) {
    winner = (winner + k) % size;        // shift the smaller game's winner by k
  }
  return winner + 1;                     // seats are 0-based, friends 1-based
}

